function scoreQA(c,d){
const n=d.narrative.trim(),ctx=d.context.trim(),all=(ctx+' '+n+' '+d.notes+' '+d.rfi).toLowerCase();
const citations=d.evidence.filter(id=>n.includes(id));const correct=d.decision===c.outcome;
const disp=correct?25:d.decision==='rfi'?11:4;
const refs=Math.min(20,d.evidence.length>=3?7+citations.length*4:citations.length*4);
const profile=Math.min(20,(ctx.length>=85?8:ctx.length>=60?5:0)+(all.includes('expected')||all.includes('baseline')||all.includes('historical')?6:0)+(all.includes('customer')||all.includes('business')||all.includes('occupation')?6:0));
const narrative=Math.min(15,(n.length>=200?8:n.length>=180?5:0)+(n.includes('TX-')?4:0)+(/\b(credit|debit|wire|transfer|funds|payment)\b/i.test(n)?3:0));
const chrono=Math.min(10,(/20\d\d|October|Oct|date/i.test(n)?5:0)+(/\$|\d[\d,]{2,}/.test(n)?5:0));
const justify=Math.min(10,(/\b(because|therefore|consistent|inconsistent|unexplained|however|explained)\b/i.test(all)?5:0)+(d.rfi.trim().length>40||/\b(uncertain|missing|request|additional|review)\b/i.test(all)?5:0));
const scores=[disp,refs,profile,narrative,chrono,justify],total=scores.reduce((a,b)=>a+b,0),passed=total>=78&&correct&&citations.length>=3;
const findings=[];
if(!correct)findings.push(['Disposition does not match training case','Your recommended outcome differs from the scenario’s reference assessment. Revisit the account context and consider alternative explanations.']);
if(citations.length<3)findings.push(['Evidence cannot be traced','Reference at least three selected transaction IDs in your narrative.']);
if(profile<15)findings.push(['Customer context needs more detail','Compare expected activity with observed funds movement and describe the material departure.']);
if(narrative<12)findings.push(['Narrative needs strengthening','Make the facts chronological, distinguish observations from inference and state the recommended action.']);
if(chrono<9)findings.push(['Timeline and amounts are incomplete','Use relevant dates, payment directions and amounts from the ledger.']);
if(justify<8)findings.push(['Explain the reasoning','State why the evidence supports your decision and what important uncertainty remains.']);
if(!findings.length)findings.push(['All required structural checks met','The educational rubric did not find a required structural revision. This is not confirmation from a human bank QA reviewer.']);
return {total,scores,passed,findings,expected:c.outcome,reason:c.why,citations:citations.length};
}
