if(d.evidence.length<3){notify('Select at least three transactions in the ledger.');return}
const matched=d.evidence.filter(x=>d.narrative.includes(x));if(matched.length<3){notify('Cite three selected transaction IDs in the narrative.');return}
if(!d.checks.kyc||!d.checks.ledger){notify('Complete KYC and transaction-review checkpoints first.');return}
if(!$('#case-attest')?.checked){notify('Confirm that your casework uses only fictional information and your own writing.');return}
if(!confirm('Submit this fictional investigation to the automated practice QA rubric? No SAR is filed and no external reviewer receives this case.'))return;
